using Microsoft.EntityFrameworkCore;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // FIX 1 (Breaking change): EF 9 renamed the discriminator JSON property
            // from "Discriminator" to "$type". Existing documents use "Discriminator".
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // FIX 2 (Breaking change): EF 9 changed the id value format from
            // "EntityType|Key" to just "Key". Existing docs have "Blog|<key>".
            // Opt back into the legacy format.
            entity.Property(b => b.Id).HasJsonPropertyName("id");

            // FIX 3 (Breaking change): HasIndex() now throws for Cosmos provider.
            // The previous HasIndex(b => b.Name) has been removed entirely.
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "BlogDb",
            cosmosOptions =>
            {
                // FIX 2 (continued): Preserve legacy "EntityType|Key" id format
                cosmosOptions.UseIdValueGeneration();
            });
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

